using System.Numerics;

class FactorialTrailingZerosCalculator
{
    // Calculates the number of trailing zeros in the factorial of a given number.
    public static int CalculateTrailingZeros(int number)
    {
        int count = 0;
        while (number >= 5)
        {
            number /= 5;
            count += number;
        }
        return count;
    }

    // Example usage
    public static void Main()
    {
        Console.WriteLine(CalculateTrailingZeros(5)); // Output: 1
        Console.WriteLine(CalculateTrailingZeros(10)); // Output: 2
        Console.WriteLine(CalculateTrailingZeros(25)); // Output: 6
    }
}
